def fill_with_blocking(grid, colors_by_color, bg=1):
    """Fill diagonals where ≥2 cells share diagonal, with blocking"""
    rows, cols = len(grid), len(grid[0])

    for val, cells in sorted(colors_by_color.items()):
        dr_counts = {}
        ur_counts = {}

        for r,c in cells:
            dr_key = c-r
            ur_key = c+r
            dr_counts[dr_key] = dr_counts.get(dr_key, 0) + 1
            ur_counts[ur_key] = ur_counts.get(ur_key, 0) + 1

        diags_to_fill = []
        for dr_key, count in dr_counts.items():
            if count >= 2:
                diags_to_fill.append(('DR', dr_key))
        for ur_key, count in ur_counts.items():
            if count >= 2:
                diags_to_fill.append(('UR', ur_key))

        for diag_type, key in diags_to_fill:
            if diag_type == 'DR':
                # Find all cells on this DR diagonal for THIS color
                dr_cells = [p for p in cells if p[1]-p[0]==key]
                if not dr_cells:
                    continue

                # Sort by column to find leftmost and rightmost
                sorted_by_c = sorted(dr_cells, key=lambda x: x[1])
                left_cell = sorted_by_c[0]   # Leftmost
                right_cell = sorted_by_c[-1]  # Rightmost

                # Extend UP-LEFT from left cell
