                # Sort by row to find topmost and bottommost
                sorted_by_r = sorted(ur_cells, key=lambda x: x[0])
                top_cell = sorted_by_r[0]    # Topmost (min row)
                bot_cell = sorted_by_r[-1]   # Bottommost (max row)

